// CONTADOR DIÁRIO: se o gasto de hoje passar do teto, a menção vai para a FILA (responde no dia seguinte).
const TETO_DIA = 1.50;          // R$ por dia útil só das menções (27/10: era 2,50; ~90 menções/dia; pior caso R$ 33/mês; teto total de IA: R$ 70/mês)
const TETO_CEO = 0.50;           // 28/10: teto SEPARADO do CEO (privado ou @), ~30 respostas/dia; não come o teto da equipe
const CEO_NOME = /Jos[ée] Redacted/i; // como o nome do CEO aparece em "quem" na tabela de consumo
const MAX_POR_RONDA = 3;
const MODELO_PADRAO = 'gemini-3.5-flash-lite';
const MODELO_RELATORIO = 'gemini-3.5-flash-lite'; // com a chave paga: 'gemini-3.5-flash'
const ESTIMATIVA = { leve: 0.05, forte: 0.25 }; // R$ por chamada, para não estourar no meio da ronda
// Perguntas sobre automações recebem o status do n8n no pacote
const SOBRE_N8N = /n8n|automa|rob[oô]|fluxo|workflow|\bata\b|\batas\b|zoom|n[aã]o saiu|n[aã]o chegou|n[aã]o veio|erro|resumo dos chats|fatura|cart[aã]o|contrato|autentique/i;
const statusN8n = ($('Resumo do n8n').first() || { json: {} }).json.texto || '';
const agora = Date.now();
const gasto = $('Gasto de hoje').all().reduce((s, i) => s + (Number(i.json.custo_brl) || 0), 0);
const prefs = $('Preferências do gestor').all().map(i => i.json).filter(p => p.descricao).map(p => '• ' + String(p.descricao).slice(0, 300)).join('\n');
// MEMÓRIA (sem IA): avaliações anteriores e base de conhecimento
const avaliacoes = $('Avaliações recentes').all().map(i => i.json).filter(a => a.id);
const base = $('Base de conhecimento recente').all().map(i => i.json).filter(b => b.descricao && b.categoria !== 'preferencia_do_gestor');
// PRIVACIDADE: registros com setor 'Restrito...' (falas do CEO) só entram no pacote quando quem mencionou é CEO ou TI.
const baseEquipe = base.filter(b => !String(b.setor || '').startsWith('Restrito'));
const exemplos = avaliacoes.filter(a => a.status === 'aprovado' && a.resposta_proposta).slice(0, 2)
  .map(a => '--- exemplo aprovado ---\n' + String(a.resposta_proposta).slice(0, 1400)).join('\n');
const palavras = t => new Set((String(t).match(/[A-ZÀ-Ý][A-Za-zÀ-ÿ]{3,}/g) || []).map(w => w.toLowerCase()).filter(w => !['para', 'próxima', 'próximo', 'relatório', 'cliente', 'clientes', 'reunião', 'contatos', 'lista', 'listas', 'resumo', 'Redacted', 'Redacted', 'contabilidade', 'foram', 'foco', 'realizar', 'manter', 'acompanhar', 'encaminhar', 'programar', 'retomar'].includes(w)));
const pend = $('Menções pendentes').all().map(i => i.json)
  .filter(m => (Number(m.tentativas) || 0) < 3)
  // "processando" há mais de 20 min = travou; tenta de novo
  .filter(m => m.status !== 'processando' || (agora - new Date(m.atualizado_em || m.updatedAt).getTime()) > 20 * 60000)
  .slice(0, MAX_POR_RONDA);
const SETORES = [
  [/comercial|\bcs\b|sucesso|relacionamento/i, 'Customer Success', 'atendimento'],
  [/fiscont|fiscal|tribut/i, 'Fiscal', 'fiscal'],
  [/\bdp\b|rh|pessoal/i, 'Departamento Pessoal', 'dp'],
  [/societ|legaliz/i, 'Legalização', 'legalizacao'],
  [/financ/i, 'Financeiro', 'atendimento'],
  [/cont[aá]b/i, 'Contábil', 'contabil'],
];
const gastoCeo = $('Gasto de hoje').all().filter(i => CEO_NOME.test(String(i.json.quem || ''))).reduce((s, i) => s + (Number(i.json.custo_brl) || 0), 0);
const somas = { equipe: gasto - gastoCeo, ceo: gastoCeo };
return pend.map(m => {
  const s = SETORES.find(x => x[0].test(m.space_nome || '')) || [null, 'Diretrizes do CEO', 'geral'];
  const texto = String(m.texto || '');
  const pareceRelatorio = /relat[oó]rio|fechamento|resumo do dia|cobertura|semáforo/i.test(texto) || texto.length > 800 || (m.anexos && m.anexos !== '[]');
  const modelo = pareceRelatorio ? MODELO_RELATORIO : MODELO_PADRAO;
  const est = modelo === MODELO_PADRAO ? ESTIMATIVA.leve : ESTIMATIVA.forte;
  const pote = m.papel === 'ceo' || CEO_NOME.test(String(m.autor || '')) ? 'ceo' : 'equipe';
  const acao = somas[pote] + est <= (pote === 'ceo' ? TETO_CEO : TETO_DIA) ? 'responder' : 'fila';
  if (acao === 'responder') somas[pote] += est;
  // Histórico da pessoa: últimas 3 avaliações de quem postou (para comparar evolução)
  const historico = avaliacoes.filter(a => a.autor === m.autor && a.message_id !== m.message_id).slice(0, 3)
    .map(a => '• ' + String(a.criado_em || a.createdAt).slice(0, 10) + ' — ' + (a.titulo_relatorio || '') + ' — nota ' + a.nota + ' — melhorias pedidas: ' + String(a.melhorias || '').replace(/\n/g, '; ').slice(0, 300)).join('\n');
  // Registros/fatos da base que citam os mesmos nomes da mensagem
  const p = palavras(texto);
  const fonte = (m.papel === 'ceo' || m.papel === 'ti') ? base : baseEquipe;
  const memoria = fonte.filter(b => { const q = palavras((b.titulo || '') + ' ' + b.descricao); for (const w of q) if (p.has(w)) return true; return false; }).slice(0, 8)
    .map(b => '• [' + String(b.data_info || b.createdAt).slice(0, 10) + ', ' + (b.categoria || '') + '] ' + (b.titulo || '') + ': ' + String(b.descricao).slice(0, 250)).join('\n');
  return { json: { ...m, acao, modelo, nota_setor: s[1], checklist: s[2], prefs, n8n_status: SOBRE_N8N.test(texto + ' ' + (m.conversa_antes || '')) ? statusN8n : '', historico, memoria, exemplos: pareceRelatorio ? exemplos : '', gasto_hoje: Math.round(gasto * 100) / 100 } };
});

// Lê o JSON do Gemini e calcula o custo (preços em US$ por 1M tokens; conferir na página do Google).
// Se o Gemini falhou ou respondeu fora do formato, tipo = "invalido" e a menção volta para a fila.
// "meta" só vale para CEO ou TI; da equipe vira "registro".
const PRECOS = { 'gemini-3.5-flash-lite': [0.30, 2.50], 'gemini-3.1-flash-lite': [0.25, 1.50], 'gemini-3.5-flash': [1.50, 9.00] };
const USD_BRL = 5.5;
const m = $('Montar pedido ao Gemini').item.json;
const r = $json;
let txt = '';
try { txt = r.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
let o = null;
try { o = JSON.parse(txt); } catch (e) { try { o = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e2) {} }
const u = r.usageMetadata || {};
const tin = u.promptTokenCount || 0;
const tout = (u.candidatesTokenCount || 0) + (u.thoughtsTokenCount || 0);
const p = PRECOS[m.modelo] || PRECOS['gemini-3.5-flash-lite'];
const custo = Math.round(((tin * p[0] + tout * p[1]) / 1e6) * USD_BRL * 10000) / 10000;
const papel = m.papel || 'equipe';
let tipo = o && o.tipo ? o.tipo : 'invalido';
if (tipo === 'meta' && papel !== 'ceo' && papel !== 'ti') tipo = 'registro';
if (o && (tipo === 'registro' || tipo === 'meta') && !String(o.registro || '').trim()) tipo = 'invalido';
if (o && tipo !== 'registro' && tipo !== 'meta' && !String(o.resposta || '').trim()) tipo = 'invalido';
o = o || {};
const erro = tipo !== 'invalido' ? '' : (r.error ? String(r.error.message || JSON.stringify(r.error)).slice(0, 300) : 'resposta do Gemini fora do formato');
return { json: { id: m.id, message_id: m.message_id, space_id: m.space_id, space_nome: m.space_nome, thread_name: m.thread_name, autor: m.autor, papel, texto: m.texto, tentativas: Number(m.tentativas) || 0, modelo: m.modelo, tipo, titulo: o.titulo || (tipo === 'meta' ? 'Meta' : 'Menção'), setor: o.setor || 'Geral', nota: Number(o.nota) || 0, pontos_fortes: o.pontos_fortes || '', riscos: o.riscos || '', melhorias: o.melhorias || '', resposta: String(o.resposta || '').slice(0, 3500), registro: o.registro || '', tokens_entrada: tin, tokens_saida: tout, custo_brl: custo, dia: $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd'), erro } };

// Gemini falhou (ex.: "high demand") ou respondeu fora do formato: a menção volta para a fila.
// Depois de 3 tentativas fica como "erro" e o Redacted é avisado. Nada é perdido nem enviado 2x.
const m = $('Interpretar resposta').item.json;
return { json: { id: m.id, autor: m.autor, space_nome: m.space_nome, texto: m.texto, tentativas: m.tentativas, status: m.tentativas >= 3 ? 'erro' : 'fila', motivo: m.erro || 'falha' } };

// Resume, SEM IA, a situação de cada automação (última execução e erros recentes).
const fl = $('Fluxos de negócio').all().map(i => i.json);
const r = $input.all().map(i => i.json);
const fmt = iso => iso ? DateTime.fromISO(String(iso)).setZone('America/Sao_Paulo').toFormat('dd/MM HH:mm') : '?';
const ST = { success: 'deu certo', error: 'ERRO', crashed: 'ERRO (travou)', running: 'rodando', waiting: 'aguardando (ex.: aprovação)', canceled: 'cancelada' };
const linhas = fl.map((f, i) => {
  const ex = (r[i] && r[i].data) || [];
  if (!ex.length) return '• ' + f.nome + ': nenhuma execução recente';
  const u = ex[0];
  const erros = ex.filter(e => e.status === 'error' || e.status === 'crashed').length;
  return '• ' + f.nome + ': última em ' + fmt(u.startedAt) + ' — ' + (ST[u.status] || u.status) + (erros ? ' (' + erros + ' erro(s) nas últimas ' + ex.length + ')' : '');
});
return [{ json: { texto: 'Consultado agora no n8n (' + fmt(new Date().toISOString()) + '):\n' + linhas.join('\n') } }];

// Acrescenta ao pacote: quem postou (CEO / TI / equipe), o tipo 'meta' e a regra de privacidade. Não muda o número de chamadas ao Gemini.
const j = $json;
const papel = j.papel || 'equipe';
const NOME = { ceo: 'CEO (Redacted Redacted, dono da empresa)', ti: 'TI (Redacted, responsável pelo Zezinho)', equipe: 'equipe' };
const extra = [
  '',
  '5) PAPEL DE QUEM POSTOU: ' + NOME[papel] + '.',
  '- META (só se o papel for CEO ou TI): se a mensagem define ou muda uma meta (objetivo com número, indicador e período para um setor ou pessoa, ex.: "meta: 3 reuniões por semana no Comercial"), use tipo "meta". No campo "registro" escreva a meta em 1 linha: SETOR — indicador — número — período — desde quando (ex.: "Comercial — reuniões realizadas — 3 por semana — a partir de 26/10"). "resposta" vazia. Se faltar número ou período, use tipo "pergunta" e peça o que falta.',
  '- Se o papel for EQUIPE, nunca use "meta": use "registro".',
  '- Se o papel for CEO e ele pedir análise, opinião ou sugestão: responda como o gestor reportando ao dono. Direto, com números e fatos do contexto, riscos, e 2-3 sugestões concretas (ação — quem — quando). Aqui PODE recomendar ao CEO. Sem base: diga o que falta e onde buscar.',
  '',
  '6) PRIVACIDADE (REGRA MÁXIMA)' + (papel === 'equipe' ? ' — quem postou é da EQUIPE:' : ':'),
  '- Nunca revele a alguém da equipe: o que o CEO disse, pediu ou registrou em particular; conversas privadas; conteúdo de espaços restritos (DP, Financeiro Interno); salários, desempenho individual de outra pessoa, decisões ainda não anunciadas, custos e contratos da REDACTED.',
  '- Se a pergunta tocar nisso, responda só o que já é público no próprio canal e diga "isso precisa ser tratado com o seu gestor". Não diga que existe informação restrita.',
  '- Elogio ou cobrança de uma pessoa só sobre o que ELA mesma postou.'
].join('\n');
j.body.systemInstruction.parts[0].text += extra;
const en = j.body.generationConfig.responseSchema.properties.tipo.enum;
if (!en.includes('meta')) en.push('meta');
j.body.contents[0].parts[0].text = 'PAPEL: ' + papel.toUpperCase() + '\n' + j.body.contents[0].parts[0].text;
return { json: j };

// SEM IA: se a menção pede ATA, pasta, gravação ou vídeo de reunião, monta a busca no Drive.
// As ATAs ficam no drive "Pastas" com nome "AAAA-MM-DD HHhMM-HHhMM — título"; o nome do cliente está no conteúdo.
// Com data: busca todas as reuniões do dia (os termos só ordenam). Sem data: busca os termos no conteúdo.
const j = $json;
const texto = String(j.texto || '').replace(/@[^\n]*?Contabilidade/gi, ' ');
const PEDE = /\bata\b|\batas\b|grava[cç][aã]o|grava[cç][oõ]es|v[ií]deo|youtube|\byt\b|transcri[cç]/i;
const NADA = "name = '__nenhum__' and trashed = false";
if (!PEDE.test(texto)) return { json: { ...j, ata: { ativo: false, q: NADA, termos: [], data: '' } } };
const hoje = $now.setZone('America/Sao_Paulo');
let data = '';
let d = texto.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
if (d) data = d[0];
else if ((d = texto.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/))) {
  const dia = Number(d[1]), mes = Number(d[2]);
  let ano = d[3] ? Number(d[3].length === 2 ? '20' + d[3] : d[3]) : hoje.year;
  if (!d[3] && (mes > hoje.month || (mes === hoje.month && dia > hoje.day))) ano -= 1;
  if (mes >= 1 && mes <= 12 && dia >= 1 && dia <= 31) data = ano + '-' + String(mes).padStart(2, '0') + '-' + String(dia).padStart(2, '0');
}
const limpa = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const PARE = new Set(('zezinho Redacted contabilidade Redacted ata atas manda mande mandar me envia envie enviar passa passe passar busca busque buscar procura procure procurar acha ache achar encontra encontre encontrar localiza localize traz traga trazer mostra mostre mostrar preciso precisa precisava quero queria pode poderia consegue favor por para pra pro link links pasta pastas video videos youtube gravacao gravacoes gravada reuniao reunioes transcricao cliente clientes oi ola bom boa dia tarde noite qual quais onde aquela aquele essa esse isso esta este dela dele com sobre das dos uma uns umas que quando ontem hoje semana passada ultima ultimo mes obrigado obrigada sim nao tem ter ver tambem mais aqui gente nossa nosso sua seu minha meu teve feita fizemos foi segunda terca quarta quinta sexta sabado domingo janeiro fevereiro marco abril maio junho julho agosto setembro outubro novembro dezembro').split(' '));
const palavras = texto.match(/[A-Za-zÀ-ÿ]{3,}/g) || [];
const maius = palavras.filter(w => /^[A-ZÀ-Ý]/.test(w) && !PARE.has(limpa(w)));
const minus = palavras.filter(w => w.length >= 5 && !PARE.has(limpa(w)));
const termos = [...new Set((maius.length ? maius : minus).map(w => w.toLowerCase()))].slice(0, 3);
const esc = s => s.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const partes = ['trashed = false', "(mimeType = 'application/vnd.google-apps.document' or mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')"];
if (data) partes.push("name contains '" + data + "'");
else termos.forEach(t => partes.push("fullText contains '" + esc(t) + "'"));
return { json: { ...j, ata: { ativo: true, q: (termos.length || data) ? partes.join(' and ') : NADA, termos, data } } };

// SEM IA: coloca no pacote do Gemini as reuniões achadas no Drive + o vídeo no YouTube (achado pelo título = nome da pasta).
// Com data, as reuniões do dia cujo título tem os termos (ex.: "comercial") vêm primeiro.
// Se algo falhar aqui, o pedido segue sem o bloco (a menção nunca trava por causa da busca).
const j = $('Pedido de ATA? (sem IA)').item.json;
if (!j.ata || !j.ata.ativo) return { json: j };
try {
  const NOME_ATA = /^(\d{4}-\d{2}-\d{2} \d{2}h\d{2})/;
  const DOC = 'application/vnd.google-apps.document';
  const limpa = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const termos = (j.ata.termos || []).map(limpa);
  const pontos = nome => termos.filter(t => limpa(nome).includes(t)).length;
  const porPasta = {};
  ($json.files || []).filter(f => NOME_ATA.test(f.name || '')).forEach(f => {
    const p = (f.parents || [])[0];
    if (p && (!porPasta[p] || f.mimeType === DOC)) porPasta[p] = f;
  });
  const videos = $('YouTube - vídeos do canal').all().flatMap(i => i.json.items || [])
    .map(v => ({ titulo: (v.snippet || {}).title || '', id: ((v.snippet || {}).resourceId || {}).videoId }));
  const lista = Object.entries(porPasta).map(([pasta, f]) => ({ pasta, f }))
    .sort((a, b) => (pontos(b.f.name) - pontos(a.f.name)) || b.f.name.localeCompare(a.f.name)).slice(0, 5);
  const linhas = lista.map((x, i) => {
    const nome = x.f.name.replace(/\.docx$/i, '');
    const v = videos.find(v => v.titulo.startsWith(nome.match(NOME_ATA)[1]));
    return (i + 1) + '. ' + nome + '\n   Pasta: <GOOGLE_URL>' + x.pasta + '\n   ATA: ' + (x.f.webViewLink || '(sem link)') + '\n   Vídeo: ' + (v ? 'https://youtu.be/' + v.id + ' (PRIVADO)' : 'não encontrado no YouTube');
  });
  const busca = 'termos: ' + (j.ata.termos.join(', ') || '—') + (j.ata.data ? ' | data: ' + j.ata.data : '');
  j.body.systemInstruction.parts[0].text += [
    '',
    '7) PEDIDO DE ATA / GRAVAÇÃO — busca automática no Drive, sem IA (' + busca + '):',
    linhas.length ? linhas.join('\n') : '(nenhuma reunião encontrada)',
    '- Se a mensagem pede ATA, pasta, gravação ou vídeo de reunião: tipo "pergunta". Responda curto e simpático com os links ACIMA no formato do Google Chat <URL|texto> (ex.: <https://...|📁 Pasta da ATA>, <https://...|📄 ATA>, <https://...|🎥 Vídeo>). Diga a data e o título da reunião.',
    '- Se uma reunião da lista bate com o que foi pedido (título/assunto), mande só ela. Se houver dúvida, liste até 5 (data + título) com os links e pergunte qual é.',
    '- Nunca invente link: use só os de cima.',
    '- O vídeo no YouTube é PRIVADO: avise que só abre para quem tem acesso ao canal; para mandar a um cliente, o Redacted (TI) libera como não listado só aquele vídeo.',
    '- Se nada foi encontrado: diga que não achou reunião gravada com esses dados e peça o nome do cliente e a data da reunião (dd/mm). Não diga que vai verificar de novo.',
    '- Não resuma o conteúdo da reunião: você não leu a ATA.'
  ].join('\n');
} catch (e) {}
return { json: j };

// SEM IA: tira até 3 termos da menção para buscar no histórico escrito (resumos de chat, ATAs, transcrições).
// 1º termos fortes: códigos de empresa (603), normas (NT 07/2026), palavras como eSocial, siglas (BNI, ILB), nomes próprios.
// Se tiver menos de 2 fortes, completa com SUBSTANTIVOS de conteúdo (ex.: planilha, levantamento, pendências); verbos ficam de fora
// porque no chat costumam estar escritos de outro jeito ("concluir" × "concluírem").
// A busca exige TODOS os termos juntos (e, se não achar, tenta com qualquer um).
const j = $json;
const texto = String(j.texto || '').replace(/@[^\n]*?Contabilidade/gi, ' ');
const limpa = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const VAZIAS = new Set(('zezinho Redacted contabilidade Redacted ceo qual quais como onde quando quem porque pelo pela pelos pelas para pra com sobre das dos uma umas uns que esta este essa esse isso aquela aquele dela dele foi era sao ser tem ter teve vai deu dar pode poderia preciso precisa quero queria favor obrigado obrigada bom boa dia tarde noite hoje ontem amanha semana mes ano data prazo regra todos todas fazer feito definido definida informado informada segunda terca quarta quinta sexta sabado domingo janeiro fevereiro marco abril maio junho julho agosto setembro outubro novembro dezembro partir qual era seria estava ficou foram').split(' '));
const SETOR = new Set('comercial fiscal contabil societario legalizacao geral operacional radar responsavel equipe setor setores empresa empresas cliente clientes'.split(' '));
const VERBO = /(rem|ram|ndo|ados|adas|ido|ida|ar|er|ir|ou|aram|eram|iram)$/i;
const fortes = [];
const ja = t => fortes.some(x => limpa(x) === limpa(t));
const addForte = t => { t = String(t).trim(); if (t && !VAZIAS.has(limpa(t)) && !SETOR.has(limpa(t)) && !ja(t)) fortes.push(t); };
(texto.match(/\b(?:NT|IN|PEC|Lei|Portaria|Edital)\s*n?[º°]?\s*\d+[\/\d.]*/gi) || []).forEach(addForte);
(texto.match(/\b\d{3,4}\b/g) || []).filter(n => !/^20\d\d$/.test(n) && !fortes.some(f => f.includes(n))).forEach(addForte);
(texto.match(/\b[a-z]+[A-Z][A-Za-z]+\b/g) || []).forEach(addForte);
(texto.match(/\b[A-Z]{2,}[A-Za-z0-9-]*\b/g) || []).filter(s => s.length >= 3).forEach(addForte);
const palavras = texto.match(/[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ-]{2,}/g) || [];
palavras.forEach((w, i) => { if (i > 0 && /^[A-ZÀ-Ý][a-zà-ÿ]/.test(w)) addForte(w); });
// 28/10: nome logo depois de "empresa/cliente/caso", mesmo em minúscula ("empresa ypiranga").
(texto.match(/\b(?:empresa|cliente|caso)\s+(?:d[aoe]\s+)?[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ0-9-]{3,}/gi) || []).forEach(m => { const w = m.split(/\s+/).pop(); if (!VAZIAS.has(limpa(w)) && !SETOR.has(limpa(w)) && !ja(w)) fortes.unshift(w); });
const termos = fortes.slice(0, 3);
if (termos.length < 2) {
  const conteudo = [...new Set(palavras.filter(w => w.length >= 6 && !VAZIAS.has(limpa(w)) && !VERBO.test(limpa(w)) && !termos.some(t => limpa(t) === limpa(w))))]
    .sort((a, b) => b.length - a.length);
  for (const w of conteudo) { if (termos.length >= 3) break; termos.push(w); }
}
// 28/10: variações de grafia para a busca com QUALQUER termo (Redacted → Redacted, Luis → Luiz). Nomes longos primeiro; máx. 4.
const variantes = [];
const addV = v => { if (v && variantes.length < 4 && !variantes.some(x => limpa(x) === limpa(v))) variantes.push(v); };
[...termos].sort((a, b) => b.length - a.length).forEach(v => { addV(v); addV(v.replace(/([a-zà-ÿ])\1/gi, '$1')); addV(v.replace(/s$/i, 'z')); addV(v.replace(/z$/i, 's')); });
return { json: { ...j, hist_termos: termos.join(', '), hist_variantes: variantes.join(', ') } };

